import sys,numpy as np
sys.path.insert(0,'/opt/tools');import casa_tool
s=casa_tool.Session();m=s.model;d=s.data
for nm in ['mobilebase0_base','mobilebase0_wheeled_base','mobilebase0_support','robot0_base']:
 i=m.body(nm).id; print('start',nm,d.xpos[i])
for k in range(25):
 a=s.initial_command();a[9]=1;a[12]=1;s.step(a)
 if k%5==4:print(k+1,'base',d.xpos[m.body('mobilebase0_base').id], 'eef',d.site_xpos[s.env.robots[0].eef_site_id['right']])
print('contacts',d.ncon)
for i in range(d.ncon):
 c=d.contact[i]; g1=m.geom(c.geom1).name;g2=m.geom(c.geom2).name
 if 'mobilebase' in g1 or 'mobilebase' in g2:
  print('contact',g1,g2,c.dist)
